new:
// Graceful shutdown: SIGTERM o Ctrl-C → flush NexusBridge (Q-table + replication)
// prima che il processo termini, per evitare perdita dati in-flight.
//
// Safety net (Bug D fix): dopo il signal e il flush, attendiamo axum::serve
// di chiudere le connessioni in-flight (SSE, long-poll). Se non si chiude
// entro 10s, forziamo `std::process::exit(0)` per evitare che il processo
// resti in 'deactivating' indefinitamente. La unit systemd ha TimeoutStopSec=15
// come ulteriore safety net (manda SIGKILL al superamento).
let shutdown_signal = async {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal, SignalKind};
        let mut terminate = signal(SignalKind::terminate())
            .expect("failed to register SIGTERM handler");
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {
                tracing::info!("Ctrl-C ricevuto — avvio graceful shutdown");
            },
            _ = terminate.recv() => {
                tracing::info!("SIGTERM ricevuto — avvio graceful shutdown");
            },
        }
    }
    #[cfg(not(unix))]
    {
        let _ = tokio::signal::ctrl_c().await;
        tracing::info!("Ctrl-C ricevuto — avvio graceful shutdown");
    }

    // Flush NexusBridge state (Q-table + replication:pending → PostgreSQL)
    if let Some(bridge) = nexus_bridge::NexusBridge::global() {
        bridge.shutdown().await;
    }

    // Safety net force-exit: se axum non si chiude entro 10s, forziamo
    // l'exit. I dati critici sono gia' stati flushati da bridge.shutdown.
    tokio::spawn(async {
        tokio::time::sleep(std::time::Duration::from_secs(10)).await;
        tracing::warn!(
            "shutdown timeout 10s superato (probabilmente SSE/long-poll in-flight), force-exit"
        );
        std::process::exit(0);
    });
};

