    // l'exit del processo. I dati critici (Q-table) sono gia' stati
    // flushati da `bridge.shutdown()`. La unit systemd ha TimeoutStopSec=15
    // come ulteriore safety net (SIGKILL forzato dopo 15s).
    tokio::spawn(async {
        tokio::time::sleep(std::time::Duration::from_secs(10)).await;
        tracing::warn!(
            "shutdown timeout 10s superato (probabilmente SSE/long-poll in-flight), force-exit"
        );
        std::process::exit(0);
    });
};

new:
    // Safety net force-exit (Bug #34): watchdog deterministico su THREAD OS
    // dedicato (std::thread), NON su tokio::spawn. Motivo del bug precedente:
    // con `#[tokio::main]`, quando `main` ritorna dopo `axum::serve().await?`
    // il runtime viene droppato; il drop attende il completamento dei task in
    // corso. Se un worker detached (provider_health_probe, deepseek_balance_sync,
    // knowledge_*_worker) o un blocco I/O e' appeso, il drop del runtime si
    // blocca e un eventuale watchdog `tokio::spawn` non viene piu' eseguito
    // (il runtime in drop non scheda nuovi task). Un std::thread e' invece
    // indipendente dal lifecycle del runtime tokio: dorme N secondi e poi
    // chiama `std::process::exit(0)` incondizionatamente, garantendo che il
    // processo (e quindi il bind su :4000) venga sempre rilasciato entro N
    // secondi anche se il graceful o il drop del runtime restano appesi.
    //
    // Il thread parte PRIMA del flush: lo stato critico (Q-table) viene
    // comunque persistito da `bridge.shutdown()` se completa entro il timeout;
    // i worker periodici non hanno stato critico non flushato (sono idempotenti
    // e ripartono al riavvio), quindi terminarli via process::exit e' sicuro.
    // La unit systemd ha TimeoutStopSec come ulteriore rete (SIGKILL).
    std::thread::spawn(move || {
        std::thread::sleep(std::time::Duration::from_secs(force_exit_timeout_secs));
        tracing::warn!(
            timeout_s = force_exit_timeout_secs,
            "watchdog shutdown: timeout superato (graceful/worker non terminati), force-exit"
        );
        std::process::exit(0);
    });

    // Flush NexusBridge state (Q-table + replication:pending → PostgreSQL).
    // Se completa prima del watchdog, l'`await?` di axum ritorna e usciamo
    // pulitamente; altrimenti il watchdog sopra garantisce l'exit.
    if let Some(bridge) = nexus_bridge::NexusBridge::global() {
        bridge.shutdown().await;
    }
};

    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal)
        .await?;

    // Uscita pulita immediata (Bug #34): a questo punto il graceful drain di axum
    // e' completo e lo stato critico e' gia' flushato (`bridge.shutdown()` nel path
    // del segnale). Chiamiamo `process::exit(0)` esplicitamente invece di lasciar
    // ritornare `main`: il drop del runtime tokio attenderebbe i worker detached
    // (provider_health_probe, deepseek_balance_sync, knowledge_*_worker) bloccando
    // potenzialmente la terminazione. process::exit termina subito e rilascia :4000.
    tracing::info!("graceful shutdown completato — exit(0)");
    std::process::exit(0);
}

