let addr = SocketAddr::from(([0, 0, 0, 0], 4000));
tracing::info!("mcp-core listening on {}", addr);

let listener = tokio::net::TcpListener::bind(addr).await?;

// Timeout del watchdog force-exit (regola G: configurabile via settings, no hardcode nascosto).
// Chiave `shutdown.force_exit_timeout_seconds` (default 10s). Letto qui, prima dello
// shutdown, perche' a shutdown il DB potrebbe gia' essere irraggiungibile.
// `state` e' gia' stato consumato dal router (`.with_state(state)`), quindi
// usiamo un clone del pool DB catturato per la lettura del setting.
let force_exit_timeout_secs: u64 = settings::get_setting(&shutdown_db, "shutdown.force_exit_timeout_seconds")

// Clone del pool DB per leggere a fine main il setting del watchdog di shutdown,
// dopo che `state` e' stato consumato dal router (`.with_state(state)`). Vedi Bug #34.
let shutdown_db = state.db.clone();

// Singleton globale per emit da contesti senza &ProjectChannels (NexusToolHandler).
nexus_events::dispatcher::init_global(state.project_channels.clone());
